# Checkout stock reservation

Allocates requested stock during checkout.

type Inventory = Record<string, number>;

export interface ReservationResult {
  allocated: Inventory;
  remaining: Inventory;
}

export function reserveInventory(
  stock: Readonly<Inventory>,
  requests: Readonly<Inventory>,
): ReservationResult {
  const allocated: Inventory = {};
  const remaining: Inventory = { ...stock };

  for (const [sku, requestedQuantity] of Object.entries(requests)) {
    if (requestedQuantity <= 0) {
      continue;
    }

    const availableQuantity = Math.max(0, stock[sku] ?? 0);
    const allocatedQuantity = Math.min(requestedQuantity, availableQuantity);

    allocated[sku] = allocatedQuantity;
    if (Object.prototype.hasOwnProperty.call(stock, sku)) {
      remaining[sku] = availableQuantity - allocatedQuantity;
    }
  }

  return { allocated, remaining };
}

